import { NextResponse } from "next/server";
import { getDb } from "@/db";
import { galleryItems } from "@/db/schema";
import { eq } from "drizzle-orm";

export async function GET(request: Request) {
  try {
    const db = getDb();

    const items = await db.select().from(galleryItems);

    return NextResponse.json({ success: true, items });
  } catch (err) {
    console.error("GET /api/gallery error:", err);
    return NextResponse.json(
      { success: false, error: "Failed to fetch gallery items" },
      { status: 500 }
    );
  }
}

export async function POST(request: Request) {
  try {
    const db = getDb();

    const body = await request.json();
    const {
      title,
      titleHi,
      description,
      category,
      mediaType,
      mediaUrl,
      thumbnailUrl,
      location,
      eventDate,
    } = body;

    if (!title || !mediaUrl || !category) {
      return NextResponse.json(
        { success: false, error: "Title, media URL, and category are required" },
        { status: 400 }
      );
    }

    const [newItem] = await db
      .insert(galleryItems)
      .values({
        title: title.trim(),
        titleHi: (titleHi || title).trim(),
        description: description ? description.trim() : null,
        category: category.toLowerCase(),
        mediaType: mediaType || "image",
        mediaUrl: mediaUrl.trim(),
        thumbnailUrl: thumbnailUrl ? thumbnailUrl.trim() : mediaUrl.trim(),
        eventDate: eventDate || null,
        location: location ? location.trim() : null,
        featured: false,
        sortOrder: 0,
      })
      .returning();

    return NextResponse.json({ success: true, item: newItem });
  } catch (err) {
    console.error("POST /api/gallery error:", err);
    return NextResponse.json(
      { success: false, error: "Failed to add gallery item" },
      { status: 500 }
    );
  }
}